CREATE OR ALTER PROCEDURE dbo.sp_log_inicio
    @id_ejecucion  VARCHAR(64),
    @pipeline      VARCHAR(100),
    @fecha_proceso VARCHAR(10)
AS
BEGIN
    -- Idempotente: si el orquestador se re-ejecuta con el mismo RunId (no deberia), no duplica
    DELETE FROM dbo.log_ejecucion WHERE id_ejecucion = @id_ejecucion;
    INSERT INTO dbo.log_ejecucion (id_ejecucion, pipeline, fecha_proceso, estado, inicio)
    VALUES (@id_ejecucion, @pipeline, @fecha_proceso, 'EnCurso', SYSUTCDATETIME());
END;

CREATE OR ALTER PROCEDURE dbo.sp_log_actividad
    @id_ejecucion     VARCHAR(64),
    @actividad        VARCHAR(100),
    @filas_leidas     BIGINT,
    @filas_escritas   BIGINT,
    @filas_cuarentena BIGINT,
    @detalle_json     VARCHAR(8000)
AS
BEGIN
    -- Idempotente: un reintento de la actividad reemplaza su fila, no agrega otra
    DELETE FROM dbo.log_actividad WHERE id_ejecucion = @id_ejecucion AND actividad = @actividad;
    INSERT INTO dbo.log_actividad
        (id_ejecucion, actividad, estado, filas_leidas, filas_escritas, filas_cuarentena, detalle_json, registrado_en)
    VALUES
        (@id_ejecucion, @actividad, 'Succeeded', @filas_leidas, @filas_escritas, @filas_cuarentena,
         LEFT(@detalle_json, 4000), SYSUTCDATETIME());
END;

CREATE OR ALTER PROCEDURE dbo.sp_log_fin
    @id_ejecucion VARCHAR(64),
    @estado       VARCHAR(20),
    @mensaje      VARCHAR(8000)
AS
BEGIN
    UPDATE dbo.log_ejecucion
    SET estado       = @estado,
        fin          = SYSUTCDATETIME(),
        duracion_seg = DATEDIFF(SECOND, inicio, SYSUTCDATETIME()),
        mensaje      = LEFT(@mensaje, 4000)
    WHERE id_ejecucion = @id_ejecucion;

    IF @estado = 'Failed'
        INSERT INTO dbo.log_error (id_ejecucion, pipeline, mensaje_error, registrado_en)
        SELECT id_ejecucion, pipeline, LEFT(@mensaje, 4000), SYSUTCDATETIME()
        FROM dbo.log_ejecucion WHERE id_ejecucion = @id_ejecucion;
END;

EXEC dbo.sp_log_inicio 'prueba-001', 'prueba_manual', '2026-08-15';
EXEC dbo.sp_log_actividad 'prueba-001', 'nb_silver_ventas', 100, 95, 5, '{"filas_leidas": 100}';
EXEC dbo.sp_log_fin 'prueba-001', 'Succeeded', '';
SELECT e.estado, a.filas_leidas, a.filas_escritas, a.filas_cuarentena FROM dbo.log_ejecucion e JOIN dbo.log_actividad a ON a.id_ejecucion = e.id_ejecucion WHERE e.id_ejecucion = 'prueba-001';
